python3 -c $'import sys,math,json\nfrom qiskit import QuantumCircuit,transpile\nfrom qiskit.circuit.library import StatePreparation\nfrom qiskit_aer import AerSimulator\nN=int(sys.argv[1])if len(sys.argv)>1 else 1000;beta=float(sys.argv[2])if len(sys.argv)>2 else 32.;shots=int(sys.argv[3])if len(sys.argv)>3 else 1024;lam=float(sys.argv[4])if len(sys.argv)>4 else .01\nassert N>=341 and beta>=0 and shots>0 and lam>=0\ndef D(n):\n b=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:return None\n  b.insert(0,r-1)\n return bytes(b)\ndef G(b):\n n=1\n for v in b:n=257*n+v+1\n return n\ndef H(b):\n return-sum((b.count(v)/len(b))*math.log2(b.count(v)/len(b))for v in set(b))\nC=[(e,b,H(b)+lam*len(b))for e in range(1,N+1)if(b:=D(e))and 83 in b]\nassert C\nC.sort(key=lambda x:(x[2],len(x[1]),x[0]));e,b,m=C[0];gap=min((x[2]-m for x in C if x[2]>m),default=1.);delta=gap/(2*len(C)+2)\nE=[x[2]+delta*i/len(C) for i,x in enumerate(C)];w=[math.exp(-beta*(v-E[0]))for v in E];z=sum(w);p=[v/z for v in w]\nn=max(1,(len(C)-1).bit_length());a=[math.sqrt(v) for v in p]+[0.]*(2**n-len(C))\nqc=QuantumCircuit(n,n);qc.append(StatePreparation(a),range(n));qc.measure(range(n),range(n));sim=AerSimulator();counts=sim.run(transpile(qc,sim),shots=shots).result().get_counts()\nprint(json.dumps({"model":"QUSM quantum encoding","N":N,"qubits":n,"candidates":len(C),"beta":beta,"winner":e,"hex":b.hex(),"roundtrip":G(b)==e,"measurement_entropy":-sum(v*math.log2(v)for v in p if v),"samples":{str(C[int(k,2)][0]):v for k,v in counts.items() if int(k,2)<len(C)},"note":"quantum circuit; classical energy enumeration; no oracle"},separators=(",",":")))' "$@"
